<script setup>
import { computed } from 'vue';
import { RouterLink } from 'vue-router';
import { useStorefront } from '../composables/useStorefront.js';
import { money } from '../utils/catalog.js';
import { SITE_NAME, SITE_PHONE, SITE_PHONE_RAW, SITE_EMAIL } from '../config/siteInfo.js';
const { readLastOrder } = useStorefront();
const order = computed(() => readLastOrder());
const delivery = computed(() => ({ standard: { label: 'Standard', eta: '3–6 business days' }, expedited: { label: 'Expedited', eta: '2–3 business days' }, priority: { label: 'Priority', eta: '1–2 business days' } }[order.value?.shipping?.method] || { label: 'Standard', eta: '3–6 business days' }));
</script>
<template><main><section v-if="!order" class="sec"><div class="wrap center fallback"><h1>Thanks for shopping with {{ SITE_NAME }}</h1><p class="lede">If you just placed an order, your confirmation is on its way to your inbox.</p><RouterLink to="/shop/" class="btn btn--pri">Continue shopping</RouterLink></div></section><section v-else class="sec"><div class="wrap ty"><div class="ty__check" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div><p class="ty__num">Order {{ order.number }}</p><h1>Thanks for shopping with us, {{ order.name.split(' ')[0] }}!</h1><p class="lede">We've received your order. A confirmation and your invoice with a secure payment link will arrive at <strong>{{ order.email }}</strong> within one business hour.</p><ol class="ty__steps"><li><strong>Invoice emailed</strong><span>Check your inbox (and spam folder) for an email from {{ SITE_EMAIL }}.</span></li><li><strong>Pay securely</strong><span>Pay by card using the link in the invoice. Sales tax is shown there.</span></li><li><strong>We ship</strong><span>Paid orders ship within 1 business day by {{ delivery.label.toLowerCase() }} shipping ({{ delivery.eta }}). You'll get a tracking number.</span></li></ol><div class="ty__grid"><div class="ty__box"><h2 class="co__h">Items</h2><div v-for="item in order.items" :key="`${item.sku}-${item.name}`" class="sum-row"><span>{{ item.qty }} × {{ item.name }}</span><span>{{ money(item.price * item.qty) }}</span></div><div class="sum-row"><span>Shipping ({{ delivery.label }})</span><span>{{ order.shipping.cost === 0 ? 'Free' : money(order.shipping.cost) }}</span></div><div class="sum-row sum-row--tot"><span>Total before tax</span><span>{{ money(order.total) }}</span></div></div><div class="ty__box"><h2 class="co__h">Shipping to</h2><p>{{ order.name }}<br>{{ order.address.join('\n') }}</p><h2 class="co__h questions">Questions?</h2><p>Email <a :href="`mailto:${SITE_EMAIL}?subject=${encodeURIComponent(`Order ${order.number}`)}`">{{ SITE_EMAIL }}</a> or call <a :href="`tel:${SITE_PHONE_RAW}`">{{ SITE_PHONE }}</a>, Mon–Fri 9–5 CT. Please include your order number.</p></div></div><div class="ty__actions"><RouterLink to="/shop/" class="btn btn--pri">Continue shopping</RouterLink><RouterLink to="/policies/returns/" class="btn btn--ghost">Returns policy</RouterLink></div></div></section></main></template>
